[InitializeOnLoad]public static class BeachDetailUpgrade{const string D="Assets/Scenes/Oasis/SouthBeach/BeachDetails";static int nearPalmTriangles,farPalmTriangles;static BeachDetailUpgrade(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BeachDetailUpgrade.request"))return;File.Delete("BeachDetailUpgrade.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BeachDetailUpgrade.txt",e.ToString());Debug.LogException(e);}}
class G{public List<Vector3> p=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<Color> colors=new List<Color>();public List<int> ids=new List<int>();public void Tri(Vector3 a,Vector3 b,Vector3 c,Color color,bool fabric=false,bool rock=false){int n=p.Count;foreach(var v in new[]{a,b,c}){p.Add(v);colors.Add(color);uv.Add(rock?new Vector2(v.x/4+v.z/6,v.y/4):fabric?new Vector2(.32f+v.x*.033f,.43f+v.z*.033f):new Vector2(.205f+v.x*.004f,.32f+v.y*.04f));}ids.AddRange(new[]{n,n+1,n+2});}public void Box(Vector3 q,Vector3 s,Color color,bool fabric=false){var v=new Vector3[8];for(int i=0;i<8;i++)v[i]=q+Vector3.Scale(new Vector3((i&1)==0?-.5f:.5f,(i&2)==0?-.5f:.5f,(i&4)==0?-.5f:.5f),s);foreach(var f in new[]{new[]{0,2,3,1},new[]{4,5,7,6},new[]{0,1,5,4},new[]{2,6,7,3},new[]{0,4,6,2},new[]{1,3,7,5}}){Tri(v[f[0]],v[f[1]],v[f[2]],color,fabric);Tri(v[f[0]],v[f[2]],v[f[3]],color,fabric);}}public void Pole(Vector3 a,Vector3 b,float r,Color color){var axis=(b-a).normalized;var u=Vector3.Cross(axis,Mathf.Abs(axis.y)>.9f?Vector3.forward:Vector3.up).normalized;var v=Vector3.Cross(axis,u);for(int k=0;k<6;k++){var x=u*Mathf.Cos(k*Mathf.PI/3)+v*Mathf.Sin(k*Mathf.PI/3);var z=u*Mathf.Cos((k+1)*Mathf.PI/3)+v*Mathf.Sin((k+1)*Mathf.PI/3);Tri(a+x*r,a+z*r,b+x*r,color);Tri(a+z*r,b+z*r,b+x*r,color);}}public Mesh Save(string name){var m=new Mesh{name=name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt16};m.SetVertices(p);m.SetUVs(0,uv);m.SetColors(colors);m.SetTriangles(ids,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();m.Optimize();AssetDatabase.CreateAsset(m,D+"/"+name+".asset");return m;}}
