static void Furniture(Material mat,Color accent,string name){G near=new G(),far=new G();Color white=new Color(.94f,.94f,.90f),wood=Color.white;for(int k=0;k<12;k++){float a=k*Mathf.PI/6,b=(k+1)*Mathf.PI/6;var top=new Vector3(0,3.12f,0);var ma=new Vector3(Mathf.Cos(a)*.95f,2.95f,Mathf.Sin(a)*.95f);var mb=new Vector3(Mathf.Cos(b)*.95f,2.95f,Mathf.Sin(b)*.95f);var u=new Vector3(Mathf.Cos(a)*1.95f,2.47f,Mathf.Sin(a)*1.95f);var v=new Vector3(Mathf.Cos(b)*1.95f,2.47f,Mathf.Sin(b)*1.95f);var color=k%2==0?accent:white;foreach(var tri in new[]{new[]{top,ma,mb},new[]{ma,u,v},new[]{ma,v,mb},new[]{u,u-Vector3.up*.13f,v},new[]{v,u-Vector3.up*.13f,v-Vector3.up*.13f}}){near.Tri(tri[0],tri[1],tri[2],color,true);near.Tri(tri[0],tri[2],tri[1],color,true);}near.Pole(new Vector3(0,2.72f,0),u,.017f,wood);}
for(int k=0;k<8;k++){float a=k*Mathf.PI/4,b=(k+1)*Mathf.PI/4;var top=new Vector3(0,3.12f,0);var u=new Vector3(Mathf.Cos(a)*1.95f,2.47f,Mathf.Sin(a)*1.95f);var v=new Vector3(Mathf.Cos(b)*1.95f,2.47f,Mathf.Sin(b)*1.95f);far.Tri(top,u,v,k%2==0?accent:white,true);far.Tri(top,v,u,k%2==0?accent:white,true);}near.Pole(Vector3.zero,new Vector3(0,3.12f,0),.05f,wood);far.Pole(Vector3.zero,new Vector3(0,3.12f,0),.05f,wood);near.Box(new Vector3(0,.07f,0),new Vector3(.42f,.14f,.42f),wood);
foreach(float x in new[]{-1.18f,1.18f}){for(int k=0;k<10;k++)near.Box(new Vector3(x,.48f,-1.15f+k*.145f),new Vector3(.72f,.055f,.10f),wood);for(int k=0;k<7;k++)near.Box(new Vector3(x,.54f+k*.12f,.25f+k*.09f),new Vector3(.72f,.09f,.10f),wood);near.Box(new Vector3(x,.54f,-.55f),new Vector3(.64f,.09f,1.13f),accent,true);near.Box(new Vector3(x,1.25f,.76f),new Vector3(.60f,.15f,.25f),white,true);foreach(float xx in new[]{x-.33f,x+.33f}){near.Pole(new Vector3(xx,.04f,-1),new Vector3(xx,.48f,-.88f),.039f,wood);near.Pole(new Vector3(xx,.04f,.25f),new Vector3(xx,.53f,.25f),.039f,wood);near.Pole(new Vector3(xx,.48f,-1.23f),new Vector3(xx,.51f,.35f),.035f,wood);near.Pole(new Vector3(xx,.51f,.22f),new Vector3(xx,1.3f,.86f),.035f,wood);near.Pole(new Vector3(xx,.72f,-.35f),new Vector3(xx,.74f,.3f),.032f,wood);}far.Box(new Vector3(x,.5f,-.5f),new Vector3(.7f,.12f,1.6f),accent,true);far.Box(new Vector3(x,.9f,.55f),new Vector3(.7f,.85f,.20f),accent,true);}near.Box(new Vector3(0,.65f,-1.5f),new Vector3(.55f,.075f,.55f),wood);near.Pole(new Vector3(0,0,-1.5f),new Vector3(0,.65f,-1.5f),.055f,wood);
var root=new GameObject(name+" colorful beach furniture");var nr=MeshChild(root,"Near cushioned chairs detailed canopy ribs",near.Save(name+" furniture near v2"),mat);var fr=MeshChild(root,"Far canopy and chair silhouettes",far.Save(name+" furniture far v2"),mat);var lod=root.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.09f,new[]{nr}),new LOD(.012f,new[]{fr})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(root,D+"/"+name+" Colorful Beach Furniture.prefab");UnityEngine.Object.DestroyImmediate(root);}
static void PalmFar(){string path=D+"/Existing Curved City Palm.prefab";var root=PrefabUtility.LoadPrefabContents(path);var sources=root.GetComponentsInChildren<MeshFilter>();var near=sources.Select(f=>f.GetComponent<Renderer>()).ToArray();var far=new List<Renderer>();foreach(var f in sources){var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var type=data.GetType();var p=(Vector3[])type.GetField("p").GetValue(data);var normals=(Vector3[])type.GetField("normal").GetValue(data);var uv=(Vector2[][])type.GetField("uv").GetValue(data);var colors=(Color[])type.GetField("colors").GetValue(data);var ids=(int[])type.GetField("ids").GetValue(data);nearPalmTriangles+=ids.Length/3;var matrix=root.transform.worldToLocalMatrix*f.transform.localToWorldMatrix;var points=new List<Vector3>();var nn=new List<Vector3>();var cc=new List<Color>();var sourceIds=new List<int>();var map=new Dictionary<string,int>();var remap=new int[p.Length];for(int i=0;i<p.Length;i++){var q=matrix.MultiplyPoint3x4(p[i]);var tex=uv[0]!=null&&uv[0].Length==p.Length?uv[0][i]:Vector2.zero;string key=Mathf.RoundToInt(q.x/.23f)+","+Mathf.RoundToInt(q.y/.23f)+","+Mathf.RoundToInt(q.z/.23f)+","+Mathf.RoundToInt(tex.x*16)+","+Mathf.RoundToInt(tex.y*16);int n;if(!map.TryGetValue(key,out n)){n=points.Count;map[key]=n;points.Add(q);nn.Add(matrix.MultiplyVector(normals[i]).normalized);cc.Add(colors!=null&&colors.Length==p.Length?colors[i]:Color.white);sourceIds.Add(i);}remap[i]=n;}var triangles=new List<int>();for(int i=0;i<ids.Length;i+=3){int a=remap[ids[i]],b=remap[ids[i+1]],c=remap[ids[i+2]];if(a==b||b==c||a==c)continue;if(Vector3.Cross(points[b]-points[a],points[c]-points[a]).sqrMagnitude<.0000001f)continue;triangles.AddRange(new[]{a,b,c});}var mesh=new Mesh{name=f.name+" beach distant clustered",indexFormat=points.Count<65535?UnityEngine.Rendering.IndexFormat.UInt16:UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(points);mesh.SetNormals(nn);mesh.SetColors(cc);for(int u=0;u<8;u++)if(uv[u]!=null&&uv[u].Length==p.Length)mesh.SetUVs(u,sourceIds.Select(i=>uv[u][i]).ToList());mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();mesh.RecalculateTangents();mesh.Optimize();AssetDatabase.CreateAsset(mesh,D+"/"+f.name+" palm distant v2.asset");farPalmTriangles+=triangles.Count/3;var r=MeshChild(root,"Far "+f.name,mesh,f.GetComponent<Renderer>().sharedMaterial);far.Add(r);}var lod=root.GetComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.075f,near),new LOD(.009f,far.ToArray())});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(root,path);PrefabUtility.UnloadPrefabContents(root);}
static void Run(){Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeBeachUpgrade");File.Copy(D+"/South Coast Beach Details.prefab","FinalEnvironmentRoadBackup/BeforeBeachUpgrade/Details.prefab",true);var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeBeachUpgrade/Scene.unity",true);var mat=AssetDatabase.LoadAssetAtPath<Material>(D+"/Beach furniture existing atlas.mat");mat.shader=Shader.Find("City/Mobile Beach Furniture Atlas");mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Scenes/Oasis/3D/Texture/Building/Building-02.jpg"));mat.SetColor("_Tint",Color.white);mat.enableInstancing=true;EditorUtility.SetDirty(mat);var palette=new[]{"Blue","Coral","Green"};Furniture(mat,new Color(.16f,.48f,.85f),palette[0]);Furniture(mat,new Color(.95f,.32f,.13f),palette[1]);Furniture(mat,new Color(.23f,.65f,.40f),palette[2]);PalmFar();var granite=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/CoastalTerrain/Crags/Shared Large Granite Faces.mat");for(int variant=0;variant<4;variant++){var geo=new G();var top=new Vector3(.15f,3.1f,-.12f);var bottom=new Vector3(0,-.5f,0);for(int k=0;k<4;k++){float a=k*Mathf.PI/2,b=(k+1)*Mathf.PI/2;var u=new Vector3(Mathf.Cos(a)*2.2f,1.1f,Mathf.Sin(a)*1.7f);var v=new Vector3(Mathf.Cos(b)*2.2f,1.1f,Mathf.Sin(b)*1.7f);geo.Tri(u,top,v,Color.white,false,true);geo.Tri(u,v,bottom,Color.white,false,true);}string path=D+"/Beach Granite Boulder "+variant+".prefab";var rock=PrefabUtility.LoadPrefabContents(path);var nr=rock.GetComponent<Renderer>();var fr=MeshChild(rock,"Far simple granite silhouette",geo.Save("Granite beach distant "+variant+" v2"),granite);var lod=rock.GetComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.07f,new[]{nr}),new LOD(.01f,new[]{fr})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(rock,path);PrefabUtility.UnloadPrefabContents(rock);}
var roads=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var shore=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Outer_MEsh");var yard=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var exclusion=yard.GetComponent<Renderer>().bounds;exclusion.Expand(new Vector3(35,40,35));var probe=new GameObject("Temporary beach ray probe");probe.transform.position=shore.transform.position;probe.transform.rotation=shore.transform.rotation;probe.transform.localScale=shore.transform.lossyScale;var collider=probe.AddComponent<MeshCollider>();collider.sharedMesh=shore.sharedMesh;Physics.SyncTransforms();var root=PrefabUtility.LoadPrefabContents(D+"/South Coast Beach Details.prefab");var rng=new System.Random(141026);Func<float,float,float> R=(a,b)=>a+(float)rng.NextDouble()*(b-a);Func<Vector3,Vector3?> Ground=q=>{q.y=28;if(exclusion.Contains(q))return null;RaycastHit hit;if(!collider.Raycast(new Ray(new Vector3(q.x,100,q.z),Vector3.down),out hit,150)||hit.point.y<25.1f)return null;return hit.point;};int furniture=0;foreach(var sector in root.transform.Cast<Transform>()){foreach(var t in sector.Cast<Transform>().ToArray()){if(t.name.ToLower().Contains("umbrella")){var pos=t.position;var rot=t.rotation;var scale=t.localScale;UnityEngine.Object.DestroyImmediate(t.gameObject);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/"+palette[furniture++%3]+" Colorful Beach Furniture.prefab"),sector);g.transform.position=pos;g.transform.rotation=rot;g.transform.localScale=scale;continue;}var p=Ground(t.position+new Vector3(R(-6,6),0,R(-6,6)));if(p.HasValue){t.position=p.Value;if(t.name.ToLower().Contains("granite"))t.position-=Vector3.up*R(.15f,.45f);}t.rotation=Quaternion.Euler(0,R(0,360),0);if(t.name.ToLower().Contains("granite"))t.localScale=Vector3.Scale(t.localScale,new Vector3(R(.85f,1.25f),R(.7f,1.1f),R(.8f,1.3f)));}}
var hull=File.ReadAllLines("FinalEnvironmentRoadReview/BeachSouthHull.csv").Select(s=>{var a=s.Split(',');return new Vector2(float.Parse(a[0],System.Globalization.CultureInfo.InvariantCulture),float.Parse(a[1],System.Globalization.CultureInfo.InvariantCulture));}).ToList();int start=hull.FindIndex(v=>v.x<0&&v.y>590);var coast=new List<Vector2>{new Vector2(0,596.75f)};for(int i=start;i<hull.Count;i++)coast.Add(hull[i]);for(int i=0;i<start&&hull[i].x<0;i++)coast.Add(hull[i]);coast.Add(new Vector2(0,-783.12f));var distances=new float[coast.Count];for(int i=1;i<distances.Length;i++)distances[i]=distances[i-1]+Vector2.Distance(coast[i],coast[i-1]);int addPalm=0,addRock=0;var existing=root.transform.Cast<Transform>().SelectMany(t=>t.Cast<Transform>()).Select(t=>t.position).ToList();for(int attempt=0;attempt<350&&(addPalm<35||addRock<50);attempt++){bool palm=attempt%2==0&&addPalm<35;if(!palm&&addRock>=50)continue;float s=R(105,distances.Last()-105);int k=1;while(k<distances.Length-1&&distances[k]<s)k++;var edge=coast[k]-coast[k-1];var normal=new Vector2(edge.y,-edge.x).normalized;var q=Vector2.Lerp(coast[k-1],coast[k],Mathf.InverseLerp(distances[k-1],distances[k],s));q+=normal*(11*Mathf.Sin(s/48)+4*Mathf.Sin(s/23+.8f)-R(palm?12:1,palm?32:15));var pos=Ground(new Vector3(q.x,28,q.y));if(!pos.HasValue||existing.Any(p=>new Vector2(p.x-pos.Value.x,p.z-pos.Value.z).sqrMagnitude<(palm?36:16)))continue;var sector=root.transform.Cast<Transform>().OrderBy(t=>{var child=t.Cast<Transform>().FirstOrDefault();return child?(child.position-pos.Value).sqrMagnitude:float.MaxValue;}).First();string path=palm?D+"/Existing Curved City Palm.prefab":D+"/Beach Granite Boulder "+(addRock%4)+".prefab";var inst=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),sector);inst.transform.position=pos.Value-(palm?Vector3.zero:Vector3.up*R(.2f,.55f));inst.transform.rotation=Quaternion.Euler(0,R(0,360),0);float scale=palm?R(.75f,1.12f):R(.45f,1.55f);inst.transform.l